 private String protocolLabel(JSONObject p){String protocol=p.optString("protocol");if(protocol.equals("amneziawg"))return "AmneziaWG";JSONObject out=p.optJSONObject("outbound"),stream=out==null?null:out.optJSONObject("streamSettings");String transport=stream==null?"":stream.optString("network"),security=stream==null?"":stream.optString("security");return protocol.toUpperCase(Locale.ROOT)+(transport.isEmpty()?"":" · "+transport.toUpperCase(Locale.ROOT))+(security.isEmpty()||security.equals("none")?"":" · "+security.toUpperCase(Locale.ROOT));}
